/**
 * Phase 2.9b — output-side safety gate for on-device generated images.
 *
 * Phase 2.9c (Task #14) was scheduled to ship a full NSFW classifier with
 * `image_blocked` telemetry and `inference_usage.metadata` migration. The
 * merged 2.9c diff only delivered the `attachment_kind` discriminator
 * column — the classifier itself was never wired (drift discovered while
 * starting Phase 2.9b). This module provides the minimum gate slice b
 * needs so on-device generated bytes are not persisted to storage without
 * a safety check; the deeper classifier (CLIP-based or platform-native)
 * lands in a follow-up.
 *
 * Contract:
 *   - `classifyGeneratedImage(bytes, mime)` returns `{ allow, reason? }`.
 *   - The gate is fail-CLOSED: any throw → `{allow: false, reason: '…'}`.
 *     A misbehaving classifier must never grant permission by default.
 *   - The gate runs CLIENT-SIDE before the bytes are uploaded. Refused
 *     bytes never touch the storage bucket.
 *
 * Today's implementation is a deterministic stub — it inspects size and
 * mime only, refuses obviously malformed payloads, and otherwise allows.
 * Slice b+1 will swap the body for a real classifier (transformers.js
 * NSFW model, on-device, no network). The CONTRACT is what matters for
 * downstream wiring — keep it stable.
 */
export type ImageSafetyVerdict =
  | { allow: true }
  | { allow: false; reason: string };

const MIN_BYTES = 64;
const MAX_BYTES = 25 * 1024 * 1024; // 25 MB hard cap on stored generated images
const ALLOWED_MIMES = new Set([
  "image/png",
  "image/jpeg",
  "image/webp",
]);

export async function classifyGeneratedImage(
  bytes: Uint8Array,
  mime: string,
): Promise<ImageSafetyVerdict> {
  try {
    if (!bytes || bytes.length < MIN_BYTES) {
      return {
        allow: false,
        reason: "Generated image is too small to be a valid image.",
      };
    }
    if (bytes.length > MAX_BYTES) {
      return {
        allow: false,
        reason: "Generated image exceeds the 25 MB safety cap.",
      };
    }
    if (!ALLOWED_MIMES.has(mime)) {
      return {
        allow: false,
        reason: `Generated image mime "${mime}" is not in the allow-list.`,
      };
    }
    // Slice b+1: real NSFW classifier goes here. Until then we accept
    // structurally-valid bytes — the stub is documented as such in the
    // CPAUD viewer when the gate produces an `allow: true` verdict.
    return { allow: true };
  } catch (err) {
    // Fail-closed: a thrown classifier must never default to allow.
    return {
      allow: false,
      reason:
        err instanceof Error
          ? `Image safety check failed: ${err.message}`
          : "Image safety check failed.",
    };
  }
}
